import{_ as t,o as a,c as r,a2 as i}from"./chunks/framework.Cm6XCzck.js";const u=JSON.parse('{"title":"Publication Center","description":"","frontmatter":{},"headers":[],"relativePath":"en/publications/index.md","filePath":"en/publications/index.md","lastUpdated":1787723028000}'),n={name:"en/publications/index.md"};function s(o,e,d,l,c,p){return a(),r("div",null,[...e[0]||(e[0]=[i(`<h1 id="publication-center" tabindex="-1">Publication Center <a class="header-anchor" href="#publication-center" aria-label="Permalink to &quot;Publication Center&quot;">​</a></h1><p>Digital Employee Works publishes versioned Runtime capabilities, Digital Employee capabilities, papers, specifications, and engineering case reports. GitHub is the single source of truth; a revision is official only after the applicable Runtime Gate, Git commit, and commit verification.</p><h2 id="current-operating-system" tabindex="-1">Current operating system <a class="header-anchor" href="#current-operating-system" aria-label="Permalink to &quot;Current operating system&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Document</th><th style="text-align:right;">Current version</th><th>Status</th></tr></thead><tbody><tr><td>Research Runtime Center</td><td><a href="./../runtime/">Operations Center</a></td><td style="text-align:right;"><strong>V5.0</strong></td><td>Frozen architecture / Running operations</td></tr><tr><td>Runtime scheduler</td><td><a href="./../runtime/v5">Research Runtime Center V5.0 specification</a></td><td style="text-align:right;"><strong>Scheduler V3.0</strong></td><td>Active / Dependency-aware recovery</td></tr><tr><td>Research intelligence</td><td><a href="./../runtime/research-intelligence">Research Intelligence System</a></td><td style="text-align:right;">V1.0</td><td>Active</td></tr></tbody></table><p>V5 defines four independent Runtime systems. Daily owns Discovery, Queue, Reading, Analysis, Production and Publication. Sunday adds 20:30 Weekly, so Sunday has seven formal same-day tasks. Scheduler uses durable Runtime facts for dependency gates, overdue catch-up and governed Blocked recovery.</p><h2 id="digital-researcher-capability" tabindex="-1">Digital Researcher capability <a class="header-anchor" href="#digital-researcher-capability" aria-label="Permalink to &quot;Digital Researcher capability&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Document</th><th style="text-align:right;">Version</th><th>Status</th></tr></thead><tbody><tr><td>Digital Employee capability</td><td><a href="./research-report-production-engine-v2.0">Research Report Production Engine</a></td><td style="text-align:right;"><strong>V2.0</strong></td><td><strong>Current Capability Release</strong></td></tr><tr><td>Usage guide</td><td><a href="./research-report-production-engine-v2.0-quickstart">V2.0 Quick Start</a></td><td style="text-align:right;">V2.0</td><td>Downloadable</td></tr><tr><td>Historical capability</td><td><a href="./research-report-production-engine-v1.3">Research Report Production Engine V1.3</a></td><td style="text-align:right;">V1.3</td><td>Historical Release</td></tr></tbody></table><p>V2.0 upgrades the system from a time-triggered research line to a dependency-driven, catch-up capable, recoverable and self-validating Digital Research Employee Runtime. GitHub cron is a wake-up signal; <code>SCHEDULER.json + Runtime Records</code> determine due work. The system enforces stage order, recovers the oldest runnable missed shift, reopens dependency-blocked work after its prerequisite completes, and validates Runtime V5 plus the human-readable Markdown ledger after control-plane changes. The 2026-08-09 Reading miss and Analysis Blocked incident is its first production Recovery Case.</p><p>Download:</p><ul><li><a href="https://github.com/joinwell52-AI/joinwell52/archive/refs/heads/main.zip" target="_blank" rel="noreferrer">Download the current source ZIP</a></li><li><a href="https://github.com/joinwell52-AI/joinwell52" target="_blank" rel="noreferrer">Open the GitHub repository</a></li></ul><p>V1.0 remains the historical baseline for the first Production Test: <a href="./research-report-production-engine-v1.0">legacy compatibility entry</a>.</p><h2 id="tmpa-publication-set" tabindex="-1">TMPA publication set <a class="header-anchor" href="#tmpa-publication-set" aria-label="Permalink to &quot;TMPA publication set&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Document</th><th style="text-align:right;">Version</th><th>Status</th></tr></thead><tbody><tr><td>Paper</td><td><a href="./tmpa-architecture-paper-a1.0">TMPA Architecture Paper</a></td><td style="text-align:right;">A1.0</td><td>Stable research-paper release; TMPA → Core → FCoP → CodeFlowMu guidance relation finalized</td></tr><tr><td>Specification</td><td><a href="./tmpa-core-specification-s1.0">TMPA Core Specification</a></td><td style="text-align:right;">S1.0</td><td>Stable normative release; Reference Reader 14/14 PASS; registered CodeFlowMu V1.8.0 product run 14/14 PASS (author-run)</td></tr><tr><td>Case report</td><td><a href="./implementation-case-i1.0">TMPA–FCoP–CodeFlowMu Implementation Case</a></td><td style="text-align:right;">I1.0</td><td>Exact-version S1.0 CodeFlowMu V1.8.0 evidence: C01–C14 14/14 author-run PASS across 71 mandatory assertions; WP-13 retained as a bounded case</td></tr></tbody></table><p>TMPA V1.0 open-science records: <a href="https://zenodo.org/records/21888488" target="_blank" rel="noreferrer">Zenodo record</a> · <a href="https://doi.org/10.5281/zenodo.21888488" target="_blank" rel="noreferrer">Zenodo DOI: 10.5281/zenodo.21888488</a> · <a href="https://osf.io/2jvqd/" target="_blank" rel="noreferrer">OSF Registration <code>2jvqd</code></a> · <a href="https://doi.org/10.17605/OSF.IO/2JVQD" target="_blank" rel="noreferrer">OSF DOI: 10.17605/OSF.IO/2JVQD</a>. The Zenodo record is the citable release archive; the OSF Registration is the immutable, timestamped registration snapshot. Both identify the complete suite, not separate records for A1.0, S1.0, and I1.0.</p><p>Release governance: <a href="./tmpa-v1.0-release-readiness-audit">TMPA V1.0 Release Readiness Audit RA1</a> identified four bounded P0 items; <a href="./tmpa-v1.0-p0-closure-rc1">RC1 closed P0-01 through P0-04</a>. The <a href="./tmpa-v1.0-release-record">final V1.0 release record</a> promotes A1.0/S1.0/I1.0 and preserves both reviews as historical evidence.</p><p>The TMPA publication suite is an independent theory layer. High-frequency Observation Notes do not automatically become paper evidence; long-term TMPA work runs through Research Program Runtime, not Daily Runtime.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Daily Discovery</span></span>
<span class="line"><span>→ Three-Column Queue</span></span>
<span class="line"><span>→ Deep Reading</span></span>
<span class="line"><span>→ Research Analysis</span></span>
<span class="line"><span>→ Publication Candidate</span></span>
<span class="line"><span>→ bilingual publication</span></span>
<span class="line"><span>→ GitHub Commit</span></span>
<span class="line"><span>→ CI / Commit Verify</span></span>
<span class="line"><span>→ Pages build</span></span>
<span class="line"><span>→ Digital Employee Works</span></span></code></pre></div><p>Until a stable release or DOI exists, citations should include author, title, explicit version, repository URL, and access date.</p>`,18)])])}const g=t(n,[["render",s]]);export{u as __pageData,g as default};
